-- Seed the existing workspace with clearly marked demo business records.
-- No Auth users, real eBay tokens, or connected marketplace sessions are created.
DO $seed$
DECLARE v_org uuid := 'd1a0a936-a447-4a3e-94a5-1f76b8f09787'; v_actor uuid;
BEGIN
 SELECT user_id INTO v_actor FROM public.organization_members
 WHERE organization_id=v_org AND is_active ORDER BY joined_at LIMIT 1;
 IF v_actor IS NULL THEN RAISE EXCEPTION 'No active workspace member; demo seed aborted'; END IF;

